entries[142882] = { ["name"] = "Rüstung zerstören", ["text"] = "Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nVerursacht 100% Waffenschaden und zerstört die Verteidigung des Ziels, wodurch seine Rüstung 6 Sek. lang um 90% verringert wird." }
