entries[142894] = { ["name"] = "Aufwärtsschlitzer", ["text"] = "8 Meter Reichweite\nWirken in 2 sek.\nSchlagt einen Feind nieder und fügt 47500 bis 52500 Schaden zu.\n\nWenn der Feind mit einem Degen pariert, wird der Angriff abgewehrt und verursacht keinen Schaden." }
entries[142895] = { ["name"] = "Zum Schweigen gebracht", ["text"] = "Unbegrenzte Reichweite\nSofort\nErzeugt ein sicheres Gebiet um das verbündete Ziel, das sofort alle Gegner 3 Sek. lang zum Schweigen bringt und sie 4 Sek. lang entwaffnet. Außerdem werden Gegner, die innerhalb des Bereichs von 'Ring des Friedens' angreifen oder Schaden verursachende Zauber einsetzen, für weitere 4 Sek. entwaffnet oder für weitere 3 Sek. zum Schweigen gebracht. 'Ring des Friedens' hält 8 Sek. lang an." }
entries[142896] = { ["name"] = "Entwaffnet", ["text"] = "Unbegrenzte Reichweite\nSofort\nErzeugt ein sicheres Gebiet um das verbündete Ziel, das sofort alle Gegner 3 Sek. lang zum Schweigen bringt und sie 4 Sek. lang entwaffnet. Außerdem werden Gegner, die innerhalb des Bereichs von 'Ring des Friedens' angreifen oder Schaden verursachende Zauber einsetzen, für weitere 4 Sek. entwaffnet oder für weitere 3 Sek. zum Schweigen gebracht. 'Ring des Friedens' hält 8 Sek. lang an." }
entries[142897] = { ["name"] = "Instabiler Umschlag", ["text"] = "Sofort\nHeilt das Ziel basierend auf der Heilmenge, die von 'Instabiler Umschlag' angesammelt wurde." }
entries[142898] = { ["name"] = "Bogenhieb", ["text"] = "100 Meter Reichweite\nSofort\nMalkorok schlägt auf den Boden und fügt allen Feinden in einem kegelförmigen Bereich von 40 Metern 810000 körperlichen Schaden zu." }
