entries[142944] = { ["name"] = "Steinabbild", ["text"] = "Sofort\nEntzieht Spielercharakteren einen Teil ihrer Lebensessenz, stößt sie zurück und fügt ihnen 148078 bis 155671 Schattenschaden zu. Aus der Lebensessenz wird eine Steinstatue erstellt.\n\nDiese Statue schlägt regelmäßig auf den Boden. Dadurch fügt sie allen Zielen in einem kegelförmigen Bereich vor ihr 217181 bis 228318 körperlichen Schaden zu und betäubt sie 4 Sek. lang. Diese Statue bleibt bestehen, bis sie getötet wird." }
entries[142945] = { ["name"] = "Schauriger Nebel", ["text"] = "100 Meter Reichweite\nSofort\nFügt dem Ziel alle 3 Sek. 121875 bis 128125 Naturschaden zu." }
entries[142947] = { ["name"] = "Blutrote Rekonstitution", ["text"] = "Unbegrenzte Reichweite\nWirken in 1.5 sek. 5 sek. Abklingzeit\nVerteilt 45 Sek. lang Animapfützen um nahe Einheiten. Alle Ziele, die sich in einem solchen Bereich aufhalten, werden pro Sekunde um 15% ihrer maximalen Gesundheit geheilt." }
entries[142948] = { ["name"] = "Zielen", ["text"] = "300 Meter Reichweite\nKanalisiert (Wirken in 6 sek.) 20 sek. Abklingzeit\nLegt auf das Ziel an. Nach 6 Sek. wird der Zaubernde ' Feuern '." }
entries[142950] = { ["name"] = "Feuern", ["text"] = "500 Meter Reichweite\nSofort\nVerursacht 4725000 körperlichen Schaden, der auf alle Ziele aufgeteilt wird. Dieser Schaden ignoriert Immunitätseffekte." }
