entries[142976] = { ["name"] = "Gehärteter prächtiger Balg", ["text"] = "Wirken in 2 sek. 1 tag Abklingzeit\nReagenzien:\nPrächtiger Balg (2)\nStellt einmal am Tag einen gehärteten prächtigen Balg aus zwei prächtigen Bälgen her. Dabei könnt Ihr Euer Wissen über pandarische Lederverarbeitung vergrößern und ein neues Schnittmuster erlernen.\nGehärteter prächtiger Balg\nWird beim Aufheben gebunden" }
