entries[142980] = { ["name"] = "Implodierende Energie", ["text"] = "100 Meter Reichweite\nSofort\nEnergie entlädt sich von Malkorok und verursacht eine Implosion. Die Implosion fügt allen Gegnern im Umkreis von 5 Metern nach 4 Sek. 585000 Schattenschaden zu. Wenn die Implosion keine Gegner trifft, verursacht sie stattdessen eine Explosion, die allen Gegnern im Umkreis von 200 Metern 688500 Schattenschaden zufügt." }
entries[142981] = { ["name"] = "Spezialisierungsfehler" }
entries[142983] = { ["name"] = "Qual", ["text"] = "Unbegrenzte Reichweite\nSofort\nQuält das Ziel mit den Schmerzen von eintausend Jahren Einsamkeit, verursacht sofort 154225 bis 155775 Schattenschaden sowie jede Folgesekunde bis zur Bannung weiteren Schattenschaden. Dieser Schaden erhöht sich mit der Zeit.\n\nJedes Mal, wenn 'Qual' gebannt wird, springt der Effekt auf ein Ziel in der Nähe über, verursacht den anfänglichen Schaden und der Schadenszuwachs wird zurückgesetzt. 'Qual' wird aufgehoben, wenn der Moguschattenritualist besiegt ist." }
